SELECT PersonId, 'ANTICHOLIN_AB' AS VarName, ABS(CHECKSUM(DrugName)) % 100000 AS DpValue, StartAt, TreatId, Caption FROM (   SELECT ot.PersonId, ot.DrugName, ot.StartAt, ot.TreatId, ai.AtcName AS Caption,     RANK() OVER ( PARTITION BY ot.PersonId ORDER BY ac.AlertLevel, ot.StartAt DESC ) AS ReverseOrder FROM dbo.OngoingTreatment ot   JOIN dbo.KBAnticholinDrug ac ON ac.ATC = ot.ATC AND ac.AlertLevel IN ( 'A','B') LEFT JOIN dbo.KBAtcIndex ai ON ai.AtcCode = ot.ATC ) agg WHERE ( PersonId IN (/*PIDS*/) ) AND ( ReverseOrder = 1 )